    conditions.push(`EXISTS (SELECT 1 FROM user_todos WHERE todo_id = todos.id AND user_id = $${params.length + 1})`);
    params.push(criteria.userId);
  }

  const query = `SELECT * FROM todos WHERE ${conditions.join(' AND ')}`;
  return executeSafeQuery<Todo>(query, params);
}

